{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "A high-transfer analogue containing the same morpholino-aniline and amide motif reached 5–6% ID peak brain radioactivity in cynomolgus monkeys by PET, demonstrating meaningful CNS access despite a large polar structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "RU-505, which shares the dimethylaminoalkyl, aromatic amide, and pyrazole features of the query, maintained brain levels equal to or greater than blood over 24 h in mice, indicating high BBB permeability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "The structurally similar [11C]GSK1838705A (aryl aminopyrimidine, methoxyaniline, amide, dimethylamino side chain) penetrated the BBB and showed moderate brain binding in mice.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Posiphen, a lipophilic basic carbamate, achieved a brain-to-plasma ratio of 5.04 in mice, supporting that high-MW basic molecules can have robust CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A second morpholine-containing radioligand analogue showed high peak brain radioactivity in cynomolgus monkeys, reinforcing the CNS penetration of this chemotype.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass. Multiple high-transfer experimental analogues with shared structural features (morpholino-aniline, aminopyrimidine, dimethylamino, amide) demonstrate meaningful brain penetration across species and PET/PK assays. This consistent supportive evidence outweighs the physicochemical prior predicting low passive permeability and efflux liability.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule.",
    "Efflux-transporter status of the query was not directly measured; high-transfer analogues may also be transporter substrates yet still achieve meaningful CNS exposure.",
    "Most supportive records are radiotracer/PET or single-dose PK studies rather than steady-state therapeutic CNS pharmacokinetics."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

